#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Cell { int* p; explicit Cell(int x): p(new int(x)) {} ~Cell() { delete p; } Cell(const Cell& x): p(x.p ? new int(*x.p) : nullptr) {} Cell& operator=(const Cell& x) { Cell tmp(x); std::swap(p, tmp.p); return *this; } Cell(Cell&& x) noexcept : p(std::exchange(x.p, nullptr)) {} Cell& operator=(Cell&& x) noexcept { if (this != &x) { delete p; p = std::exchange(x.p, nullptr); } return *this; } int get() const { return p ? *p : 0; } };
int solve(int a, int b) { Cell x{a}; Cell y = x; Cell z(std::move(y)); Cell empty = y; x = z; x = std::move(z); *x.p = b; return x.get() + y.get() + z.get() + empty.get(); }
